    outputs: [],
  },
] as const

function buildAuthorityCall({
  chainId,
  authority,
  target,
  abi,
  functionName,
  args,
  contractName,
  gas,
  label,
}: {
  chainId: JBChainId
  authority: Address
  target: Address
  abi: Abi
  functionName: string
  args: readonly unknown[]
  contractName: string
  gas?: bigint
  label: string
}): AuthorityCall {
  return {
    chainId,
    authority,
    target,
    data: encodeFunctionData({ abi, functionName, args }),
    abi,
    functionName,
    args,
    contractName,
    ...(gas === undefined ? {} : { gas }),
    label,
  }
}

