  poolSummary: string
  readError: string | null
}

type ActionKind = 'hook' | 'terminal' | 'pool' | 'setPool' | 'twap'

/** `JBBuybackHook._requireValidTwapWindow`: 5 minutes to 2 days. */
const MIN_TWAP_WINDOW = 300
const MAX_TWAP_WINDOW = 172_800

type Review = {
  calls: AuthorityCall[]
  rows: TxConfirmRow[]
  /** The same actions as tray steps, one per selected chain. */
  steps: BatchStep[]
}

const ACTIONS: Record<
  ActionKind,
  {
    title: string
    description: string
    danger: string
