describe('minimum-drop disclosure', () => {
  const args = { decimals: 18, symbol: 'ETH' }

  it('stays silent when the minimum holds or improves', () => {
    expect(
      minimumDropNotice({
        ...args,
        displayedMinimum: 10n ** 18n,
        freshMinimum: 10n ** 18n,
      }),
    ).toBeUndefined()
    expect(
      minimumDropNotice({
        ...args,
        displayedMinimum: 10n ** 18n,
        freshMinimum: 2n * 10n ** 18n,
      }),
    ).toBeUndefined()
  })

  it('names both figures on ANY drop — there is no tolerance band', () => {
    const notice = minimumDropNotice({
      ...args,
      displayedMinimum: 10n ** 18n,
      freshMinimum: (10n ** 18n * 99n) / 100n,
    })
    expect(notice).toMatch(/dropped since you reviewed/)
    expect(notice).toContain('was at least 1 ETH')
    expect(notice).toContain('now at least 0.99 ETH')
  })

  it('widens precision rather than printing the same figure twice', () => {
    // A one-wei drop rounds to the same display string (and is below JS
    // number precision) — the warning must still show two different numbers.
    const notice = minimumDropNotice({
      ...args,
      displayedMinimum: 10n ** 18n,
      freshMinimum: 10n ** 18n - 1n,
    })
    expect(notice).toContain('was at least 1 ETH')
    expect(notice).toContain('now at least 0.999999999999999999 ETH')
  })

  it('stays silent with nothing to compare against', () => {
    expect(
      minimumDropNotice({ ...args, displayedMinimum: null, freshMinimum: 1n }),
    ).toBeUndefined()
  })
})

/**
 * Adapter from the indexed movement row used by this app to the SDK's
 * on-chain, root-verified sucker movement and claim primitives.
 */
import {
  claimFromSuckerMovement,
  getAccountingContexts,
  getSuckerMovements,
  suckerAccountingContextKey,
  suckerBytes32ToAddress,
  type JBClaim,
} from '@bananapus/nana-sdk-core/v6'
import type { JBChainId } from '@bananapus/nana-sdk-core'
import { isAddressEqual, type Address, type PublicClient } from 'viem'
import type { BridgeMovement } from '@/lib/suckers-queries'

export async function buildClaim(
  sourceClient: PublicClient,
  destinationClient: PublicClient,
  indexed: BridgeMovement,
  projects?: {
    sourceProjectId: bigint
    destinationProjectId: bigint
  },
): Promise<JBClaim> {
  let historicalRemoteToken: Address | undefined
  if (projects) {
    const sourceChainId = indexed.sourceChainId as JBChainId
    const destinationChainId = indexed.destChainId as JBChainId
    const [sourceContexts, destinationContexts] = await Promise.all([
      getAccountingContexts(sourceClient, {
        chainId: sourceChainId,
        projectId: projects.sourceProjectId,
      }),
      getAccountingContexts(destinationClient, {
        chainId: destinationChainId,
        projectId: projects.destinationProjectId,
      }),
    ])
    const sourceContext = sourceContexts.find(context =>
      isAddressEqual(context.token, indexed.token as Address),
    )
    if (sourceContext) {
      const sourceKey = suckerAccountingContextKey(
        sourceContext.token,
        sourceChainId,
        sourceContext.decimals,
      )
      const candidates = destinationContexts.filter(
        context =>
          suckerAccountingContextKey(
            context.token,
            destinationChainId,
            context.decimals,
          ) === sourceKey,
      )
      historicalRemoteToken =
        candidates.length === 1 ? candidates[0].token : undefined
    }
  }

  const movements = await getSuckerMovements(
    sourceClient,
    destinationClient,
    {
      sourceSucker: indexed.sourceSucker as Address,
      destinationSucker: indexed.destSucker as Address,
      sourceToken: indexed.token as Address,
      remoteToken: historicalRemoteToken,
    },
  )
  const movement = movements.find(
    candidate => candidate.leaf.index === BigInt(indexed.index),
  )
  if (!movement) throw new Error('This move is not in the sucker outbox.')

  // Claim status comes from the CHAIN, not the indexer. The movement list this client shows
  // is assembled from indexed outbox/claim rows, so under indexer lag a move that was
  // already claimed still offers a Claim button (and one just claimed elsewhere would too).
  // The SDK verified this leaf against the destination inbox root, so its status is
  // authoritative — refuse rather than send a transaction that must revert.
  if (movement.status === 'claimed') {
    throw new Error('This move has already been claimed on the destination chain.')
  }
  if (movement.status === 'pending' || !movement.proof) {
    throw new Error(
      'This move has not been delivered to the destination chain yet — it cannot be claimed until its root arrives.',
    )
  }

  // The indexer is only used to select a row. Refuse the claim if its visible
  // identity disagrees with the SDK's verified event preimage.
  if (
    !isAddressEqual(
      suckerBytes32ToAddress(movement.leaf.beneficiary),
      indexed.beneficiary as Address,
    ) ||
    movement.leaf.projectTokenCount !== BigInt(indexed.projectTokenCount) ||
    movement.leaf.terminalTokenAmount !== BigInt(indexed.terminalTokenAmount)
  ) {
    throw new Error(
      'The indexed bridge movement does not match its verified on-chain leaf.',
    )
  }

  return claimFromSuckerMovement(movement)
}

// Claim status must come from the CHAIN, not the indexer. jbm assembles its movement list
// from indexed outbox/claim rows, so under indexer lag an already-claimed move still shows a
// Claim button — and a move whose root hasn't arrived yet looks claimable too. The SDK
// verifies each leaf against the destination inbox root, so its `status` is authoritative;
// `buildClaim` refuses rather than sending a transaction that must revert.
import { buildClaim } from '@/lib/sucker-claims'
import { describe, expect, it, vi } from 'vitest'
import type { PublicClient } from 'viem'

const LEAF = {
  index: 7n,
  beneficiary: `0x${'00'.repeat(12)}${'11'.repeat(20)}` as const,
  projectTokenCount: 1000n,
  terminalTokenAmount: 500n,
}

const indexed = {
  index: 7,
  sourceSucker: '0x1111111111111111111111111111111111111111',
  destSucker: '0x2222222222222222222222222222222222222222',
  token: '0x3333333333333333333333333333333333333333',
  beneficiary: `0x${'11'.repeat(20)}`,
  projectTokenCount: '1000',
  terminalTokenAmount: '500',
  sourceChainId: 1,
  destChainId: 8453,
} as unknown as Parameters<typeof buildClaim>[2]

function movementWith(status: string, proof: unknown = { branch: [], leaf: LEAF }) {
  return [{ leaf: LEAF, status, proof }]
}

const mocks = vi.hoisted(() => ({ getSuckerMovements: vi.fn() }))
vi.mock('@bananapus/nana-sdk-core/v6', async (importOriginal) => ({
  ...(await importOriginal<Record<string, unknown>>()),
  getSuckerMovements: mocks.getSuckerMovements,
  claimFromSuckerMovement: () => ({ ok: true }),
}))

const client = {} as PublicClient

describe('buildClaim status gate', () => {
  it('refuses a movement the chain says is already claimed', async () => {
    mocks.getSuckerMovements.mockResolvedValue(movementWith('claimed'))
    await expect(buildClaim(client, client, indexed)).rejects.toThrow(/already been claimed/i)
  })

  it('refuses a movement whose root has not been delivered yet', async () => {
    mocks.getSuckerMovements.mockResolvedValue(movementWith('pending', null))
    await expect(buildClaim(client, client, indexed)).rejects.toThrow(/not been delivered/i)
  })

  it('refuses a claimable movement that carries no verified proof', async () => {
    mocks.getSuckerMovements.mockResolvedValue(movementWith('claimable', null))
    await expect(buildClaim(client, client, indexed)).rejects.toThrow(/not been delivered/i)
  })

  it('builds the claim when the chain says it is claimable and proved', async () => {
    mocks.getSuckerMovements.mockResolvedValue(movementWith('claimable'))
    await expect(buildClaim(client, client, indexed)).resolves.toEqual({ ok: true })
  })
})

import {
  JBCENTER_DEFAULT_URL,
  JBCenterRequestError,
  JBCenterTimeoutError,
  createJBCenterClient,
  type JBCenterClientOptions,
  type JBCenterJsonObject,
  type JBCenterPin,
} from '@bananapus/nana-sdk-core/jbcenter'
import { jbCenterBaseUrl } from '@/lib/jbcenter-config'

export const JBCENTER_IPFS_GATEWAY = `${JBCENTER_DEFAULT_URL}/ipfs/`
/** CIDv0 of a zero-byte file — what a pin returns when the browser handed us an
 *  empty File (undownloaded cloud files, cross-site drags) or the body was lost. */
const EMPTY_FILE_CID = 'QmbFMke1KXqnYyBBWxB74N4c5SBnJMVAiMNRcGu6x1AwQH'
export const JBCENTER_MAX_IMAGE_BYTES = 25 * 1024 * 1024
export const JBCENTER_MAX_MEDIA_BYTES = 500 * 1024 * 1024

type BrowserClientOptions = Pick<JBCenterClientOptions, 'baseUrl' | 'fetch'>

export type JBCenterIpfsClient = {
  pinJson(value: Record<string, unknown>): Promise<JBCenterPin>
  pinImage(file: File): Promise<JBCenterPin>
  pinMedia(file: File): Promise<JBCenterPin>
}

/**
 * Browser-only Juicebox Center IPFS adapter.
 *
 * Approved web clients call Center directly and let the browser send its
 * `Origin`. Never add a Center API key here: a NEXT_PUBLIC key is public, and
 * server keys are for non-browser integrations only.
 */
export function createJBCenterIpfsClient(
  options: BrowserClientOptions = {},
): JBCenterIpfsClient {
  const center = createJBCenterClient({
    baseUrl: jbCenterBaseUrl(),
    ...options,
  })

  const friendly = async <T>(label: string, request: Promise<T>): Promise<T> => {
    try {
      return await request
    } catch (error) {
      if (
        error instanceof JBCenterRequestError ||
        error instanceof JBCenterTimeoutError
      ) {
        throw new Error(`${label}: ${error.message}`, { cause: error })
      }
      throw new Error(`${label} — try again.`, { cause: error })
    }
  }

  const nonEmpty = async (file: File, request: Promise<JBCenterPin>) => {
    if (file.size === 0) {
      throw new Error(
        `"${file.name || 'file'}" is empty (0 bytes). If it lives in iCloud or another cloud drive, open it on this device first, then choose it again.`,
      )
    }
    const pin = await request
    if (pin.cid === EMPTY_FILE_CID) {
      throw new Error(
        `"${file.name || 'file'}" uploaded as empty. Choose the file again and retry.`,
      )
    }
    return pin
  }

  return {
    pinJson(value) {
      // Values assembled from optional form fields contain `undefined`, which
      // JSON intentionally omits. Normalize once so the SDK receives exactly
      // the JSON object the user reviewed and custom fields round-trip safely.
      let json: unknown
      try {
        json = JSON.parse(JSON.stringify(value))
      } catch (error) {
        throw new Error('This metadata cannot be represented as JSON.', {
          cause: error,
        })
      }
      if (typeof json !== 'object' || json === null || Array.isArray(json)) {
        throw new Error('Metadata must be a JSON object.')
      }
      return friendly(
        'Saving metadata failed',
        center.pinJson(json as JBCenterJsonObject),
      )
    },
    pinImage(file) {
      return nonEmpty(
        file,
        friendly(
          'Image upload failed',
          center.pinImage(file, { filename: file.name || 'image' }),
        ),
      )
    },
    pinMedia(file) {
      return nonEmpty(
        file,
        friendly(
          'Media upload failed',
          center.pinMedia(file, { filename: file.name || 'media' }),
        ),
      )
    },
  }
}

export const jbCenterIpfs = createJBCenterIpfsClient()

