      .reduce((sum, issuance) => sum + issuance.count, 0n)
    expect(minted).toBe(count)
  })

  it('keeps stage configs byte-identical with rows minting on different chains', () => {
    const chains = [1, 10, 8453] as const
    const revnetPlan = plan({
      flavor: 'revnet',
      operator: BOB,
      ticker: 'REV',
      chains: [...chains],
      linkChains: true,
      stages: [
        {
