      saltNonce: 7n,
    }
    const call = {
      target: CANONICAL_FACTORY,
      data: '0xabcd' as Hex,
      abi: [],
      functionName: 'createProxyWithNonce' as const,
      args: [CANONICAL_SINGLETON, '0x1234' as Hex, 7n] as const,
    }
    const deploy = (reverifyAuthority = vi.fn().mockResolvedValue(undefined)) =>
