const PROJECTS = `
  query Projects($where: projectFilter!, $limit: Int!) {
    projects(where: $where, limit: $limit) {
      totalCount
      items { chainId projectId version name }
    }
  }
`;
const OPERATION = createHash("sha256").update(PROJECTS).digest("hex");

afterEach(() => {
  vi.unstubAllGlobals();
