/**
 * App-level sentinel convention used by Juicebox 721 shops for effectively
 * unlimited inventory.
 */
export const TIER_UNLIMITED_SUPPLY = 999_999_999;

export { DISCOUNT_DENOMINATOR, effectiveTierPrice } from "./tierPrice.js";

/**
 * The one JBOmnichainDeployer function the 721 hook lookup reads, so a page
 * that resolves a hook does not load the deployer's whole ABI.
 */
const tiered721HookOfAbi = [
  {
    type: "function",
    inputs: [
      { name: "projectId", internalType: "uint256", type: "uint256" },
      { name: "rulesetId", internalType: "uint256", type: "uint256" },
    ],
    name: "tiered721HookOf",
    outputs: [
      {
        name: "hook",
        internalType: "contract IJB721TiersHook",
        type: "address",
      },
      { name: "useDataHookForCashOut", internalType: "bool", type: "bool" },
    ],
    stateMutability: "view",
  },
] as const;

/** The 721 tiers hook's ruleset-metadata bit which pauses eligible transfers. */
export const JB721_RULESET_METADATA_PAUSE_TRANSFERS = 1 << 0;

/** The 721 tiers hook's ruleset-metadata bit which pauses pending reserve mints. */
export const JB721_RULESET_METADATA_PAUSE_MINT_PENDING_RESERVES = 1 << 1;

/** The protocol stores 14 app-specific bits in `JBRulesetMetadata.metadata`. */
export const JB_RULESET_METADATA_APP_BITS_MAX = 0x3fff;

/** 721-specific overrides accepted by {@link build721RulesetMetadata}. */
export interface JB721RulesetMetadataInput {
  /** Existing app-specific metadata. Unrelated bits are preserved. */
  metadata?: number;
  /** Pause transfers for tiers whose `transfersPausable` flag is enabled. */
  pauseTransfers?: boolean;
  /** Pause minting the hook's pending reserve tokens. */
  pauseMintPendingReserves?: boolean;
}

/** 721-specific flags decoded from app-specific ruleset metadata. */
export interface JB721RulesetMetadata {
  pauseTransfers: boolean;
  pauseMintPendingReserves: boolean;
}

function assertRulesetAppMetadata(metadata: number): void {
  if (
    !Number.isInteger(metadata) ||
    metadata < 0 ||
    metadata > JB_RULESET_METADATA_APP_BITS_MAX
  ) {
    throw new Error(
      `Ruleset app metadata must be an integer between 0 and ${JB_RULESET_METADATA_APP_BITS_MAX}.`,
    );
  }
}

function setMetadataFlag(
  metadata: number,
  flag: number,
  enabled: boolean | undefined,
): number {
  if (enabled === undefined) return metadata;
  return enabled ? metadata | flag : metadata & ~flag;
}

/**
 * Set the 721 tiers hook's ruleset flags while preserving every unrelated app
 * metadata bit. This is important when composing with other hooks; for
 * example, Revnets use another bit to permit sucker deployment.
 *
 * A transfer is only paused when `pauseTransfers` is true AND the transferred
 * tier was created with `transfersPausable`. Mints and burns remain possible.
 * Omitted overrides preserve the corresponding bit in `metadata`.
 */
export function build721RulesetMetadata(
  input: JB721RulesetMetadataInput = {},
): number {
  const metadata = input.metadata ?? 0;
  assertRulesetAppMetadata(metadata);

  return setMetadataFlag(
    setMetadataFlag(
      metadata,
      JB721_RULESET_METADATA_PAUSE_TRANSFERS,
      input.pauseTransfers,
    ),
    JB721_RULESET_METADATA_PAUSE_MINT_PENDING_RESERVES,
    input.pauseMintPendingReserves,
  );
}

/** Decode the 721 tiers hook's flags without interpreting unrelated bits. */
export function decode721RulesetMetadata(
  metadata: number,
): JB721RulesetMetadata {
  assertRulesetAppMetadata(metadata);
  return {
    pauseTransfers: (metadata & JB721_RULESET_METADATA_PAUSE_TRANSFERS) !== 0,
    pauseMintPendingReserves:
      (metadata & JB721_RULESET_METADATA_PAUSE_MINT_PENDING_RESERVES) !== 0,
  };
}

/** Canonical display fields understood across Juicebox 721 metadata writers. */
export interface TierMetadata {
  name?: string;
  description?: string;
  image?: string;
  animationUrl?: string;
  mediaType?: string;
  categoryName?: string;
}

/** Input accepted by {@link buildTierMetadata}. */
export interface TierMetadataInput {
  name: string;
  description?: string;
  image?: string;
  animationUrl?: string;
  mediaType?: string;
  categoryName?: string;
}

/** JSON shape written for a tier's pinned metadata. */
export interface StoredTierMetadata {
  name: string;
  description?: string;
  image?: string;
  animation_url?: string;
  mediaType?: string;
  categoryName?: string;
}

function nonEmptyString(value: unknown): string | undefined {
  return typeof value === "string" && value ? value : undefined;
}

function decodeBase64Utf8(value: string): string {
  const binary = atob(value);
  return new TextDecoder().decode(
    Uint8Array.from(binary, (character) => character.charCodeAt(0)),
  );
}

/**
 * Parse a `data:application/json` tier URI. Invalid, non-object, and non-data
 * values return `null` so callers can fall back to an IPFS metadata fetch.
 */
export function parseTierMetadataJson(
  uri: string,
): Record<string, unknown> | null {
  if (!uri.startsWith("data:application/json")) return null;
  const comma = uri.indexOf(",");
  if (comma === -1) return null;

  try {
    const header = uri.slice(0, comma);
    const payload = uri.slice(comma + 1);
    const json = JSON.parse(
      header.split(";").includes("base64")
        ? decodeBase64Utf8(payload)
        : decodeURIComponent(payload),
    ) as unknown;
    return json !== null && typeof json === "object" && !Array.isArray(json)
      ? (json as Record<string, unknown>)
      : null;
  } catch {
    return null;
  }
}

/**
 * Normalize legacy and current tier metadata field names into one display
 * shape. Only non-empty strings are returned.
 */
export function pickTierMetadata(json: Record<string, unknown>): TierMetadata {
  return {
    name: nonEmptyString(json.productName) ?? nonEmptyString(json.name),
    description:
      nonEmptyString(json.productDescription) ??
      nonEmptyString(json.description),
    image: nonEmptyString(json.image) ?? nonEmptyString(json.imageUri),
    animationUrl:
      nonEmptyString(json.animation_url) ?? nonEmptyString(json.animationUrl),
    mediaType:
      nonEmptyString(json.mediaType) ??
      nonEmptyString(json.animationType) ??
      nonEmptyString(json.mimeType),
    categoryName: nonEmptyString(json.categoryName),
  };
}

/** Whether a tier media value uses an immutable or browser-loadable URI form. */
export function isSafeTierMediaUri(value: string): boolean {
  const uri = value.trim();
  if (!uri || /\s/.test(uri)) return false;

  const ipfsPath = ipfsAssetPath(uri);
  if (ipfsPath && isIpfsCid(ipfsPath.split("/")[0])) return true;
  if (isIpfsCid(uri.split("/")[0])) return true;
  if (/^data:(image|audio|video)\/[a-z0-9.+-]+[;,]/i.test(uri)) return true;

  try {
    const url = new URL(uri);
    return url.protocol === "https:" || url.protocol === "http:";
  } catch {
    return false;
  }
}

/** Build the canonical JSON object pinned for one tier. */
export function buildTierMetadata(
  input: TierMetadataInput,
): StoredTierMetadata {
  const name = input.name.trim();
  if (!name) throw new Error("Tier name is required.");

  const optional = (value: string | undefined) => value?.trim() || undefined;
  const image = optional(input.image);
  const animationUrl = optional(input.animationUrl);
  const mediaType = optional(input.mediaType);
  if (image && !isSafeTierMediaUri(image)) {
    throw new Error(
      "Tier images must use IPFS, HTTP, HTTPS, or an image data URI.",
    );
  }
  if (animationUrl && !isSafeTierMediaUri(animationUrl)) {
    throw new Error(
      "Tier animations must use IPFS, HTTP, HTTPS, or a media data URI.",
    );
  }
  if (
    mediaType &&
    !/^[a-z0-9!#$&^_.+-]+\/[a-z0-9!#$&^_.+-]+$/i.test(mediaType)
  ) {
    throw new Error("Tier media type must be a valid MIME type.");
  }

  return {
    name,
    description: optional(input.description),
    image,
    animation_url: animationUrl,
    mediaType,
    categoryName: optional(input.categoryName),
  };
}

/**
 * Route IPFS media through a caller-selected gateway base URL. Data URIs and
 * ordinary HTTP URLs pass through unchanged.
 */
export function tierMediaAssetUrl(
  value: unknown,
  ipfsGatewayBaseUrl = "https://ipfs.io/ipfs/",
): string | undefined {
  if (typeof value !== "string" || !value) return undefined;
  if (value.startsWith("data:")) return value;
  const trimmed = value.trim();
  const path =
    ipfsAssetPath(trimmed) ??
    (isIpfsCid(trimmed.split("/")[0]) ? trimmed : null);
  if (!path) return value;
  return `${ipfsGatewayBaseUrl.replace(/\/?$/, "/")}${path}`;
}

function svgDataUriMarkup(uri: string): string | null {
  const match = /^data:image\/svg\+xml([^,]*),([\s\S]*)$/.exec(uri);
  if (!match) return null;
  try {
    return match[1].split(";").includes("base64")
      ? decodeBase64Utf8(match[2])
      : decodeURIComponent(match[2]);
  } catch {
    return null;
  }
}

/**
 * Return a browser-renderable tier image URL. SVG data URIs that only wrap an
 * external `<image href>` are unwrapped because browsers block that nested
 * network request when the SVG itself is used as an `<img>` source.
 */
export function tierMediaImageUrl(
  image: unknown,
  ipfsGatewayBaseUrl?: string,
): string | undefined {
  if (typeof image !== "string" || !image) return undefined;
  const markup = svgDataUriMarkup(image);
  if (markup) {
    const href = /<image[^>]+href=["']([^"']+)["']/.exec(markup)?.[1];
    if (href && !href.startsWith("data:")) {
      return tierMediaAssetUrl(href, ipfsGatewayBaseUrl);
    }
    return image;
  }
  return tierMediaAssetUrl(image, ipfsGatewayBaseUrl);
}

/** Pick and resolve all tier metadata fields in one pass. */
export function tierDisplayMetadata(
  json: Record<string, unknown>,
  ipfsGatewayBaseUrl?: string,
): TierMetadata {
  const metadata = pickTierMetadata(json);
  return {
    ...metadata,
    image: tierMediaImageUrl(metadata.image, ipfsGatewayBaseUrl),
    animationUrl: tierMediaAssetUrl(metadata.animationUrl, ipfsGatewayBaseUrl),
  };
}

/** Stable first-seen category ids, with blank categories assigned to 0. */
export function buildTierCategoryPlan(
  tiers: ReadonlyArray<{ id: string; categoryName?: string }>,
): {
  categoryByTierId: Record<string, number>;
  storeCategories: Record<string, string>;
} {
  const categoryIds = new Map<string, number>();
  const categoryByTierId: Record<string, number> = {};
  const storeCategories: Record<string, string> = {};

  for (const tier of tiers) {
    const name = tier.categoryName?.trim() || "";
    if (!name) {
      categoryByTierId[tier.id] = 0;
      continue;
    }
    let category = categoryIds.get(name);
    if (category === undefined) {
      category = categoryIds.size + 1;
      categoryIds.set(name, category);
      storeCategories[String(category)] = name;
    }
    categoryByTierId[tier.id] = category;
  }

  return { categoryByTierId, storeCategories };
}

/**
 * A single 721 tier a project sells.
 */
export interface Project721Tier {
  id: number;
  /** Full (undiscounted) price in the shop's pricing terms. */
  price: bigint;
  remainingSupply: number;
  initialSupply: number;
  votingUnits: bigint;
  reserveFrequency: number;
  category: number;
  /** Out of 200 — see {@link DISCOUNT_DENOMINATOR}. */
  discountPercent: number;
  encodedIpfsUri: Hex;
  /** tokenUriResolver output (data URI), or "" if the hook has no resolver. */
  resolvedUri: string;
}

/**
 * A project's resolved 721 tiers hook ("shop"): the hook, its store, the
 * metadata id target for pay/cash-out metadata, the pricing context, and tiers.
 */
export interface Project721Shop {
  /** The project's 721 tiers hook (the ruleset data hook / revnet hook). */
  hook: Address;
  /** The hook's tiers store. */
  store: Address;
  /**
   * The hook's `METADATA_ID_TARGET` (shared implementation address). Pass this
   * to {@link build721PayMetadata} / {@link build721CashOutMetadata}, never the
   * `hook` address.
   */
  metadataIdTarget: Address;
  /** The hook's pricing context: `currency` id and `decimals`. */
  pricing: { currency: number; decimals: number };
  tiers: Project721Tier[];
  /**
   * The current ruleset (with decoded metadata) when hook resolution had to
   * read it — every non-revnet project. `null` for revnets, whose hook comes
   * from `REVOwner` without a ruleset read. Reuse it instead of calling
   * `getCurrentRuleset` again.
   */
  ruleset: JBRulesetWithMetadata | null;
}

/**
 * Read a JB721 hook's `METADATA_ID_TARGET` — the shared *implementation* address
 * that pay/cash-out metadata ids must key off (a delegatecall clone reports the
 * implementation, not itself). Falls back to `hook` ONLY when the contract
 * itself answered that it has no such getter (a revert or empty return — an
 * older, non-clone hook). Transport/RPC failures are rethrown: treating them as
 * "old hook" would key pay metadata off the clone address, which the hook
 * silently ignores — the payer pays and receives no NFT.
 *
 * @param client A viem public client on the given chain.
 * @param args.hook The project's 721 tiers hook (clone) address.
 */
export async function get721MetadataIdTarget(
  client: PublicClient,
  { hook }: { chainId: JBChainId; hook: Address },
): Promise<Address> {
  return client
    .readContract({
      address: hook,
      abi: jb721TiersHookAbi,
      functionName: "METADATA_ID_TARGET",
    })
    .catch((error: unknown) => {
      if (isMissingContractFunctionError(error)) return hook;
      throw error;
    });
}

/** Resolve the shop hook/store without requiring pricing or tier reads.
 * Missing custom hook capabilities return null; transport failures propagate.
 * `includeInactiveHook` also inspects a configured but disabled pay hook.
 */
export async function resolveProject721Hook(
  client: PublicClient,
  {
    chainId,
    projectId,
    isRevnet,
    ruleset: suppliedRuleset,
    includeInactiveHook = false,
  }: {
    chainId: JBChainId;
    projectId: bigint;
    isRevnet: boolean;
    ruleset?: JBRulesetWithMetadata;
    includeInactiveHook?: boolean;
  },
): Promise<{
  hook: Address;
  store: Address;
  ruleset: JBRulesetWithMetadata | null;
} | null> {
  // 1. Resolve the 721 hook.
  let hook: Address | null = null;
  // A non-authoritative candidate is the ruleset data hook, which might be some
  // other kind of hook; the STORE() probe below decides.
  let authoritative = true;
  let currentRuleset: JBRulesetWithMetadata | null = null;

  if (isRevnet) {
    const revnetHook = await getRevnetTiered721Hook(client, {
      chainId,
      revnetId: projectId,
    });
    hook = revnetHook !== zeroAddress ? revnetHook : null;
  } else {
    currentRuleset =
      suppliedRuleset ??
      (await getCurrentRuleset(client, { chainId, projectId }));
    const { ruleset, metadata } = currentRuleset;
    const dataHook = metadata.dataHook as Address;
    if (
      (metadata.useDataHookForPay || includeInactiveHook) &&
      dataHook &&
      dataHook !== zeroAddress
    ) {
      const omni = jbV6ContractAddress[
        JBOmnichainDeployerContracts.JBOmnichainDeployer
      ]?.[chainId] as Address | undefined;
      if (omni && dataHook.toLowerCase() === omni.toLowerCase()) {
        // Omnichain project: the real 721 hook lives in the deployer's
        // per-ruleset mapping.
        const [omniHook] = await client.readContract({
          address: omni,
          abi: tiered721HookOfAbi,
          functionName: "tiered721HookOf",
          args: [projectId, BigInt(ruleset.id)],
        });
        hook = omniHook !== zeroAddress ? omniHook : null;
      } else {
        // Single-chain custom project: the data hook may be the 721 hook itself.
        hook = dataHook;
        authoritative = false;
      }
    }
  }
  if (!hook) return null;

  // 2. The hook's store. For a non-authoritative candidate a PROVEN revert (or
  // empty return) means "not a 721 hook" — no shop. Transport failures prove
  // nothing and are rethrown; swallowing them would render "no shop" for a
  // project that has one. For an authoritative hook, let every failure throw.
  const readStore = () =>
    client.readContract({
      address: hook!,
      abi: jb721TiersHookAbi,
      functionName: "STORE",
    });
  const store = authoritative
    ? await readStore()
    : await readStore().catch((error: unknown) => {
        if (isMissingContractFunctionError(error)) return null;
        throw error;
      });
  if (!store) return null;

  return { hook, store, ruleset: currentRuleset };
}

/**
 * Resolve a project's 721 tiers hook, its store, metadata id target, pricing
 * context, and tiers in one call.
 *
 * Hook resolution mirrors the app patterns: revnets read
 * `REVOwner.tiered721HookOf`; custom projects read the current ruleset's pay
 * data hook — either the omnichain deployer (the real hook lives in
 * `JBOmnichainDeployer.tiered721HookOf(projectId, rulesetId)`) or the 721 hook
 * itself, verified by probing `STORE()` (a proven revert or empty return means
 * it is not a 721 hook, so the project has no shop).
 *
 * Returns `null` only when the project authoritatively has no 721 shop. RPC and
 * transport failures throw — on authoritative reads and on the `STORE()` probe
 * alike — so a transient error surfaces as an error rather than a false
 * "no shop".
 *
 * @param client A viem public client on the given chain.
 * @param args.projectId The project (or revnet) id.
 * @param args.isRevnet Whether the project is a revnet (changes hook resolution).
 * @param args.tierLimit Max tiers to read from `tiersOf`. Defaults to 100.
 * @param args.categories Tier categories to filter by (empty = all). Defaults to `[]`.
 * @param args.startingId Inclusive sorted-tier cursor for pagination. Defaults to `0n`.
 * @param args.ruleset A previously read current ruleset, avoiding another read.
 * @param args.includeInactiveHook Inspect the configured hook even when pay is disabled. Defaults to `false`.
 * @param args.includeResolvedUri Ask the store to run the hook's token URI
 * resolver for every tier (`tiersOf`'s `includeResolvedUri`). Defaults to
 * `false`: resolver output (often inline SVG data URIs) is packed into one
 * eth_call return, and over a large shop the upstream RPC rejects it. Turn it
 * on only for small reads that need `resolvedUri` without an indexer.
 */
export async function getProject721Shop(
  client: PublicClient,
  {
    chainId,
    projectId,
    isRevnet,
    tierLimit = 100,
    categories = [],
    includeResolvedUri = false,
    startingId = 0n,
    ruleset,
    includeInactiveHook = false,
  }: {
    chainId: JBChainId;
    projectId: bigint;
    isRevnet: boolean;
    tierLimit?: number;
    categories?: bigint[];
    includeResolvedUri?: boolean;
    startingId?: bigint;
    ruleset?: JBRulesetWithMetadata;
    includeInactiveHook?: boolean;
  },
): Promise<Project721Shop | null> {
  const resolved = await resolveProject721Hook(client, {
    chainId,
    projectId,
    isRevnet,
    ruleset,
    includeInactiveHook,
  });
  if (!resolved) return null;
  const { hook, store, ruleset: currentRuleset } = resolved;

  // 3. Metadata id target + pricing context. Pricing is meaningless without the
  // hook's exact currency + decimals, so a failure here is an error, not a
  // fallback.
  const [metadataIdTarget, pricingRaw] = await Promise.all([
    get721MetadataIdTarget(client, { chainId, hook }),
    client.readContract({
      address: hook,
      abi: jb721TiersHookAbi,
      functionName: "pricingContext",
    }),
  ]);

  // 4. The tiers. Resolver URIs are opt-in (see `includeResolvedUri`).
  const raw = await client.readContract({
    address: store,
    abi: jb721TiersHookStoreAbi,
    functionName: "tiersOf",
    args: [hook, categories, includeResolvedUri, startingId, BigInt(tierLimit)],
  });

  const tiers: Project721Tier[] = raw
    .filter((tier) => tier.initialSupply > 0)
    .map((tier) => ({
      id: tier.id,
      price: tier.price,
      remainingSupply: tier.remainingSupply,
      initialSupply: tier.initialSupply,
      votingUnits: tier.votingUnits,
      reserveFrequency: tier.reserveFrequency,
      category: tier.category,
      discountPercent: tier.discountPercent,
      encodedIpfsUri: tier.encodedIpfsUri,
      resolvedUri: tier.resolvedUri ?? "",
    }));

  return {
    hook,
    store,
    metadataIdTarget,
    pricing: {
      currency: Number(pricingRaw[0]),
      decimals: Number(pricingRaw[1]),
    },
    tiers,
    ruleset: currentRuleset,
  };
}

