import {
  Address,
  Hex,
  PublicClient,
  encodeAbiParameters,
  getAddress,
  zeroAddress,
} from "viem";
import {
  DEFAULT_ALLOW_OVERSPENDING,
  MAX_RESERVED_PERCENT,
  NATIVE_TOKEN,
} from "../constants.js";
import {
  jbBuybackHookRegistryAbi,
  jbMultiTerminalAbi,
} from "../generated/juicebox.js";
import { JBChainId } from "../types.js";
import { createHookMetadata, hookMetadataId } from "../utils/hook.js";
