const FROM = "0x1111111111111111111111111111111111111111" as Address;
const TARGET = "0x2222222222222222222222222222222222222222" as Address;

const rawClient = (result: unknown) =>
  ({
    request: vi.fn().mockResolvedValue(result),
  }) as unknown as PublicClient & {
    request: ReturnType<typeof vi.fn>;
  };

describe("state-changing transaction simulation", () => {
  it("uses a raw, explicitly gas-bounded eth_call", async () => {
    const client = rawClient("0x");
    await expect(
      simulateStateChangingTransaction(client, {
        from: FROM,
        to: TARGET,
        data: "0x1234",
        value: 7n,
      }),
    ).resolves.toBe("0x");
    expect(client.request).toHaveBeenCalledWith({
      method: "eth_call",
      params: [
        {
          from: FROM,
          to: TARGET,
          data: "0x1234",
          value: "0x7",
          gas: `0x${TRANSACTION_SIMULATION_GAS.toString(16)}`,
        },
        "latest",
      ],
    });
  });

  it("simulates at a given block with the caller's gas", async () => {
    const client = rawClient("0xabcd");
    await expect(
      simulateStateChangingTransaction(client, {
        from: FROM,
        to: TARGET,
        data: "0x1234",
        gas: 500_000n,
        blockNumber: 12_345n,
      }),
    ).resolves.toBe("0xabcd");
    expect(client.request).toHaveBeenCalledWith({
      method: "eth_call",
      params: [
        {
          from: FROM,
          to: TARGET,
          data: "0x1234",
          value: "0x0",
          gas: "0x7a120",
        },
        "0x3039",
      ],
    });
  });

  it("never follows a target-controlled OffchainLookup URL", async () => {
    const request = vi
      .fn()
      .mockRejectedValue(
        new Error(
          "execution reverted: OffchainLookup(https://127.0.0.1/private)",
        ),
      );
    const fetchSpy = vi.spyOn(globalThis, "fetch");
    await expect(
      simulateStateChangingTransaction(
        { request, ccipRead: true } as unknown as PublicClient,
        { from: FROM, to: TARGET, data: "0x1234" },
      ),
    ).rejects.toThrow(/OffchainLookup/);
    expect(fetchSpy).not.toHaveBeenCalled();
    fetchSpy.mockRestore();
  });

  it("rejects oversized or malformed return data before a caller decodes it", async () => {
    const simulate = (result: unknown, maxReturnBytes?: number) =>
      simulateStateChangingTransaction(rawClient(result), {
        from: FROM,
        to: TARGET,
        data: "0x1234",
        maxReturnBytes,
      });
    await expect(
      simulate(`0x${"00".repeat(TRANSACTION_SIMULATION_MAX_RETURN_BYTES + 1)}`),
    ).rejects.toThrow(/too much data/);
    await expect(
      simulate(`0x${"00".repeat(TRANSACTION_SIMULATION_MAX_RETURN_BYTES)}`),
    ).resolves.toMatch(/^0x/);
    await expect(simulate(`0x${"00".repeat(33)}`, 32)).rejects.toThrow(
      /too much data/,
    );
    await expect(simulate(`0x${"00".repeat(32)}`, 32)).resolves.toMatch(/^0x/);
    for (const malformed of [null, 7, "0x123", "0xzz", "1234"]) {
      await expect(simulate(malformed)).rejects.toThrow(/malformed data/);
    }
  });

  it("refuses an unbounded simulation", async () => {
    const client = rawClient("0x");
    for (const gas of [0n, -1n]) {
      await expect(
        simulateStateChangingTransaction(client, {
          from: FROM,
          to: TARGET,
          data: "0x",
          gas,
        }),
      ).rejects.toThrow("Transaction simulation gas must be positive.");
    }
    for (const maxReturnBytes of [-1, 1.5, Number.NaN]) {
      await expect(
        simulateStateChangingTransaction(client, {
          from: FROM,
          to: TARGET,
          data: "0x",
          maxReturnBytes,
        }),
      ).rejects.toThrow("Transaction simulation needs a return data limit.");
    }
    expect(client.request).not.toHaveBeenCalled();
  });
});

describe("ordered call sequence simulation", () => {
  const calls = [
    { to: TARGET, data: "0x01" as Hex, label: "Approve the pool" },
    {
      to: FROM,
      data: "0x02" as Hex,
      value: 3n,
      label: "Add liquidity",
      dependsOnPrior: true,
    },
  ];
  const sequenceClient = (
    simulateCalls: ReturnType<typeof vi.fn>,
    request = vi.fn().mockResolvedValue("0x"),
  ) =>
    ({ simulateCalls, request }) as unknown as PublicClient & {
      request: ReturnType<typeof vi.fn>;
    };
  const simulate = (client: PublicClient) =>
    simulateCallSequence(client, { from: FROM, calls, chainName: "Base" });

  it("runs every call in order against one state with eth_simulateV1", async () => {
    const simulateCalls = vi.fn().mockResolvedValue({
      results: [{ status: "success" }, { status: "success" }],
    });
    const client = sequenceClient(simulateCalls);
    await expect(simulate(client)).resolves.toBeUndefined();
    expect(simulateCalls).toHaveBeenCalledWith({
      account: FROM,
      calls: [
        { to: TARGET, data: "0x01", value: undefined },
        { to: FROM, data: "0x02", value: 3n },
      ],
    });
    expect(client.request).not.toHaveBeenCalled();
  });

  it("names the call that fails and why", async () => {
    const revert = Object.assign(new Error("execution reverted\ndetails"), {
      shortMessage: "Allowance too low",
    });
    await expect(
      simulate(
        sequenceClient(
          vi.fn().mockResolvedValue({
            results: [
              { status: "success" },
              { status: "failure", error: revert },
            ],
          }),
        ),
      ),
    ).rejects.toThrow("Add liquidity cannot run on Base: Allowance too low");
    await expect(
      simulate(
        sequenceClient(
          vi.fn().mockResolvedValue({
            results: [
              { status: "failure", error: new Error("first line\nsecond") },
            ],
          }),
        ),
      ),
    ).rejects.toThrow("Approve the pool cannot run on Base: first line");
    // A missing result is never read as success.
    await expect(
      simulate(
        sequenceClient(
          vi.fn().mockResolvedValue({ results: [{ status: "success" }] }),
        ),
      ),
    ).rejects.toThrow(
      "Add liquidity cannot run on Base: The call would revert.",
    );
  });

  it("stops when the sequence itself cannot be simulated", async () => {
    await expect(
      simulate(
        sequenceClient(vi.fn().mockRejectedValue(new Error("reverted"))),
      ),
    ).rejects.toThrow("The batch could not be simulated on Base: reverted");
    await expect(
      simulate(sequenceClient(vi.fn().mockRejectedValue(undefined))),
    ).rejects.toThrow(
      "The batch could not be simulated on Base: The call would revert.",
    );
    await expect(
      simulate(sequenceClient(vi.fn().mockRejectedValue({ code: -32000 }))),
    ).rejects.toThrow(
      "The batch could not be simulated on Base: The call would revert.",
    );
  });

  it("falls back to each independent call alone where the node lacks eth_simulateV1", async () => {
    for (const unsupported of [
      { code: -32601 },
      { code: -32004 },
      { cause: { cause: { code: -32601 } } },
      new Error("the method eth_simulateV1 does not exist/is not available"),
      new Error("Method not supported"),
      { details: "eth_simulateV1 is not supported on this network" },
      // A viem error is read by its details, never its message.
      {
        shortMessage: "RPC Request failed.",
        message: "RPC Request failed. Details: header not found",
        details: "Unsupported method: eth_simulateV1",
      },
    ]) {
      const client = sequenceClient(vi.fn().mockRejectedValue(unsupported));
      await expect(simulate(client)).resolves.toBeUndefined();
      // The dependent call is left to the executing wallet's simulation.
      expect(client.request).toHaveBeenCalledTimes(1);
      expect(client.request.mock.calls[0][0].params[0]).toMatchObject({
        from: FROM,
        to: TARGET,
        data: "0x01",
      });
    }
    const failing = sequenceClient(
      vi.fn().mockRejectedValue({ code: -32601 }),
      vi.fn().mockRejectedValue(new Error("execution reverted: no allowance")),
    );
    await expect(simulate(failing)).rejects.toThrow(
      "Approve the pool cannot run on Base: execution reverted: no allowance",
    );
  });

  it("never reads a revert or another node error as eth_simulateV1 being unavailable", async () => {
    for (const error of [
      // A reason, even one naming eth_simulateV1, is the call's own revert.
      new Error("execution reverted: Project not found"),
      new Error("execution reverted: eth_simulateV1 is not supported"),
      new Error("header not found"),
      { code: -32603, message: "Internal error" },
      // viem's message quotes the request body, which names the method.
      {
        shortMessage: "RPC Request failed.",
        message:
          'RPC Request failed. Request body: {"method":"eth_simulateV1"} Details: header not found',
        details: "header not found",
      },
      {
        shortMessage: "Missing or invalid parameters.",
        message: "method not found",
      },
    ]) {
      const client = sequenceClient(vi.fn().mockRejectedValue(error));
      await expect(simulate(client)).rejects.toThrow(
        /^The batch could not be simulated on Base: /,
      );
      expect(client.request).not.toHaveBeenCalled();
    }
  });
});

describe("call sequence simulation through viem", () => {
  const calls = [
    { to: TARGET, data: "0x01" as Hex, label: "First" },
    { to: TARGET, data: "0x02" as Hex, label: "Second", dependsOnPrior: true },
  ];
  /** A real viem client whose node fails eth_simulateV1 with `error`. */
  function node(error: { code: number; message: string; data?: Hex }) {
    const methods: string[] = [];
    const client = createPublicClient({
      chain: base,
      transport: custom(
        {
          async request({ method }: { method: string }) {
            methods.push(method);
            if (method === "eth_simulateV1") {
              throw Object.assign(new Error(error.message), error);
            }
            if (method === "eth_call") return "0x";
            throw new Error(`Unexpected ${method}`);
          },
        },
        { retryCount: 0 },
      ),
    });
    return { client, methods };
  }

  it("falls back when the node has no eth_simulateV1", async () => {
    for (const error of [
      {
        code: -32601,
        message: "the method eth_simulateV1 does not exist/is not available",
      },
      { code: -32004, message: "Method not supported" },
      // Some nodes answer with a generic code and name the method.
      {
        code: -32000,
        message: "the method eth_simulateV1 does not exist/is not available",
      },
    ]) {
      const { client, methods } = node(error);
      await expect(
        simulateCallSequence(client, { from: FROM, calls, chainName: "Base" }),
      ).resolves.toBeUndefined();
      expect(methods).toEqual(["eth_simulateV1", "eth_call"]);
    }
  });

  it("stops on a revert or an internal error instead of skipping dependent calls", async () => {
    for (const error of [
      {
        code: 3,
        message: "execution reverted: Project not found",
        data: "0x08c379a0" as Hex,
      },
      {
        code: 3,
        message: "execution reverted: the method eth_simulateV1 does not exist",
        data: "0x08c379a0" as Hex,
      },
      { code: -32603, message: "Internal error" },
    ]) {
      const { client, methods } = node(error);
      await expect(
        simulateCallSequence(client, { from: FROM, calls, chainName: "Base" }),
      ).rejects.toThrow(/^The batch could not be simulated on Base: /);
      expect(methods).toEqual(["eth_simulateV1"]);
    }
  });
});

// The network guard stubs fetch before every test; this is the real one.
const loopbackFetch = globalThis.fetch;

describe("call sequence simulation over viem's HTTP transport", () => {
  const calls = [
    { to: TARGET, data: "0x01" as Hex, label: "First" },
    { to: TARGET, data: "0x02" as Hex, label: "Second", dependsOnPrior: true },
  ];
  let server: Server;
  let url: string;
  let simulateError: { code: number; message: string; data?: Hex };
  let methods: string[];

  beforeAll(async () => {
    // A local JSON-RPC node: eth_simulateV1 fails with `simulateError`,
    // eth_call succeeds.
    server = createServer((request, response) => {
      let body = "";
      request.on("data", (chunk) => (body += chunk));
      request.on("end", () => {
        const answer = ({ id, method }: { id: number; method: string }) => {
          methods.push(method);
          return method === "eth_simulateV1"
            ? { jsonrpc: "2.0", id, error: simulateError }
            : { jsonrpc: "2.0", id, result: "0x" };
        };
        const message = JSON.parse(body);
        response.setHeader("content-type", "application/json");
        response.end(
          JSON.stringify(
            Array.isArray(message) ? message.map(answer) : answer(message),
          ),
        );
      });
    });
    await new Promise<void>((resolve) =>
      server.listen(0, "127.0.0.1", resolve),
    );
    url = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  });

  afterAll(async () => {
    await new Promise((resolve) => server.close(resolve));
  });

  beforeEach(() => {
    methods = [];
    // Only this suite's loopback node may answer.
    vi.stubGlobal(
      "fetch",
      vi.fn((input: string | URL | Request, init?: RequestInit) =>
        String(input) === url
          ? loopbackFetch(input, init)
          : Promise.reject(new Error(`Unexpected fetch: ${String(input)}`)),
      ),
    );
  });

  const simulate = () =>
    simulateCallSequence(
      createPublicClient({
        chain: base,
        transport: http(url, { retryCount: 0 }),
      }),
      { from: FROM, calls, chainName: "Base" },
    );

  it("falls back when the node reports the method missing", async () => {
    for (const error of [
      {
        code: -32601,
        message: "the method eth_simulateV1 does not exist/is not available",
      },
      { code: -32000, message: "method not found" },
      { code: -32004, message: "Method not supported" },
      {
        code: -32600,
        message: "Unsupported method: eth_simulateV1. See available methods.",
      },
    ]) {
      simulateError = error;
      methods = [];
      await expect(simulate()).resolves.toBeUndefined();
      expect(methods).toEqual(["eth_simulateV1", "eth_call"]);
    }
  });

  it("fails closed on a lagging node, bad parameters or a revert", async () => {
    for (const error of [
      { code: -32000, message: "header not found" },
      { code: -32000, message: "resource not found" },
      { code: -32602, message: "field not allowed: validation" },
      {
        code: 3,
        message: "execution reverted: Project not found",
        data: "0x08c379a0" as Hex,
      },
    ]) {
      simulateError = error;
      methods = [];
      await expect(simulate()).rejects.toThrow(
        /^The batch could not be simulated on Base: /,
      );
      expect(methods).toEqual(["eth_simulateV1"]);
    }
  });
});

import { Address, ContractFunctionArgs, PublicClient } from "viem";
import { revDeployerAbi, revOwnerAbi } from "../generated/juicebox.js";
import { JBChainId } from "../types.js";
import {
  buildRevnet721Config,
  resolve721PricingContext,
  type Revnet721OperatorPermissions,
} from "./revnet721.js";
import { JBAccountingContext } from "./terminals.js";
import { selectDeploymentAbi } from "./deploymentAbi.js";
import { v6Address } from "./types.js";

type RevDeployArgs = ContractFunctionArgs<
  typeof revDeployerAbi,
  "payable",
  "deployFor"
>;

type RevDeployArgs6 = Extract<
  RevDeployArgs,
  readonly [unknown, unknown, unknown, unknown, unknown, unknown]
>;

type RevDeployArgs4 = Extract<
  RevDeployArgs,
  readonly [unknown, unknown, unknown, unknown]
>;

/**
 * A revnet's full configuration: its token description (name/ticker/uri and
 * the salt that fixes the ERC-20's deterministic address), base currency
 * (either a token-keyed currency or a well-known `JBCurrencyIds` id such as
 * ETH=1 or USD=2), operator, and stage configurations.
 */
export type REVConfig = RevDeployArgs4[1];

/**
 * One stage of a revnet's lifecycle. See `buildRevnetStageConfig` for the
 * field encodings.
 */
export type REVStageConfig = REVConfig["stageConfigurations"][number];

/**
 * An auto-issuance: tokens minted without payment when a stage starts, to a
 * beneficiary on a specific chain. `count` is an 18-decimal fixed point.
 */
export type REVAutoIssuance = REVStageConfig["autoIssuances"][number];

/**
 * Sucker deployment configuration for a revnet (same shape the omnichain
 * deployer takes; build with `parseSuckerDeployerConfig(..., { version: 6 })`).
 */
export type REVSuckerDeploymentConfig = RevDeployArgs4[3];

/**
 * Configuration for deploying a tiered 721 hook alongside a revnet.
 */
export type REVDeploy721TiersHookConfig = RevDeployArgs6[4];

/**
 * A croptop allowed-post configuration: which 721 categories third parties
 * may post to, and at what minimum price/supply.
 */
export type REVCroptopAllowedPost = RevDeployArgs6[5][number];

/**
 * Ruleset `extraMetadata` bit 2: allows `REVDeployer.deploySuckersFor` to extend
 * the revnet to new chains while the stage is active (the deployer checks
 * `(metadata >> 2) & 1`). `extraMetadata` is folded into the revnet's immutable
 * encoded-configuration hash, so a stage without this bit can NEVER be extended —
 * there is no later fix.
 */
export const REV_METADATA_ALLOW_SUCKER_DEPLOYMENT = 1 << 2;

/**
 * Build a `REVStageConfig` (spec-exact encodings, documented per field).
 *
 * ENCODINGS:
 * - `startsAtOrAfter`: ABSOLUTE unix timestamp (uint48), strictly increasing
 *   across stages. For omnichain revnets, compute every stage's start as a
 *   cumulative offset from ONE shared deploy-start timestamp so the stage
 *   list is byte-identical on every chain.
 * - `splitPercent`: the share of issuance routed to splits, out of 10,000
 *   (e.g. 3,800 = 38%).
 * - `splits[].percent`: each split's share of the SPLIT BUCKET (not of total
 *   issuance), out of 1e9; the group must total exactly 1e9 — use
 *   `fillSplitPercents`.
 * - `initialIssuance`: tokens minted per unit of base currency, 18-decimal
 *   fixed point (uint112). The exported `RULESET_WEIGHT_INHERIT` sentinel
 *   (1n) means "inherit the previous stage's issuance with its cuts applied";
 *   zero means genuine zero issuance.
 * - `issuanceCutFrequency`: seconds between issuance cuts (should be >= 1
 *   day; it becomes the stage's ruleset duration).
 * - `issuanceCutPercent`: how much issuance drops each period, out of 1e9
 *   (`MAX_WEIGHT_CUT_PERCENT`; e.g. 20% = 200,000,000).
 * - `cashOutTaxRate`: out of 10,000 (`MAX_CASH_OUT_TAX_RATE`). Any non-zero
 *   rate makes EVERY cash out incur the 2.5% protocol fee; zero-tax cash outs
 *   still pay it on `min(reclaimAmount, feeFreeSurplusOf)`, which is often
 *   but not always zero.
 * - `extraMetadata`: extra metadata bits forwarded to hooks.
 *   {@link REV_METADATA_ALLOW_SUCKER_DEPLOYMENT} (bit 2) is ORed in by default
 *   so the revnet stays extendable to new chains; pass
 *   `allowSuckerDeployment: false` to opt out PERMANENTLY for the stage.
 */
export function buildRevnetStageConfig(args: {
  startsAtOrAfter: number;
  initialIssuance: bigint;
  autoIssuances?: readonly REVAutoIssuance[];
  splitPercent?: number;
  splits?: REVStageConfig["splits"];
  issuanceCutFrequency?: number;
  issuanceCutPercent?: number;
  cashOutTaxRate?: number;
  extraMetadata?: number;
  /**
   * Whether `REVDeployer.deploySuckersFor` may extend the revnet to new chains
   * during this stage. Defaults to TRUE — a stage without the bit is
   * un-extendable forever, since stages are immutable once deployed.
   */
  allowSuckerDeployment?: boolean;
}): REVStageConfig {
  const extraMetadata =
    args.allowSuckerDeployment === false
      ? (args.extraMetadata ?? 0)
      : (args.extraMetadata ?? 0) | REV_METADATA_ALLOW_SUCKER_DEPLOYMENT;
  return {
    startsAtOrAfter: args.startsAtOrAfter,
    autoIssuances: args.autoIssuances ?? [],
    splitPercent: args.splitPercent ?? 0,
    splits: args.splits ?? [],
    initialIssuance: args.initialIssuance,
    issuanceCutFrequency: args.issuanceCutFrequency ?? 0,
    issuanceCutPercent: args.issuanceCutPercent ?? 0,
    cashOutTaxRate: args.cashOutTaxRate ?? 0,
    extraMetadata,
  };
}

/**
 * Build a `REVDeployer.deployFor` transaction request deploying a new revnet
 * Every canonical v6 revnet has a 721 shop, including the four-argument overload.
 * Omit shop configuration to retain the contract defaults, or use
 * `tiered721Config` / `default721Config` to choose pricing and operator powers.
 *
 * Deploying a NEW revnet (`revnetId` 0n) is payable and must send EXACTLY the
 * current project creation fee — read it with `getProjectCreationFee` on the
 * same chain. Deploying for an EXISTING project must send no value (the
 * deployer reverts otherwise), so `creationFee` is ignored in that case.
 * For omnichain revnets, send one transaction per chain with an identical
 * `config` (shared description salt, shared absolute stage starts) and a
 * shared sucker salt.
 *
 * @param args.config The revnet configuration; see {@link REVConfig}.
 * @param args.accountingContexts The tokens the revnet accepts as reserves;
 * see `buildAccountingContext`.
 * @param args.suckerConfig Cross-chain sucker configuration (empty
 * `deployerConfigurations` for a single-chain revnet); build with
 * `parseSuckerDeployerConfig(chainId, chainIds, assets, { version: 6 })`.
 * @param args.revnetId The revnet to deploy for. Defaults to 0n (create a
 * NEW revnet).
 * @param args.tiered721Config Optional tiered 721 hook config — switches to
 * the 6-arg overload.
 * @param args.allowedPosts Croptop posting rules (only used with
 * `tiered721Config`). Defaults to none.
 */
export function buildDeployRevnetTx(args: {
  chainId: JBChainId;
  config: REVConfig;
  accountingContexts: readonly JBAccountingContext[];
  suckerConfig: REVSuckerDeploymentConfig;
  creationFee?: bigint;
  revnetId?: bigint;
  tiered721Config?: REVDeploy721TiersHookConfig;
  /** Build an empty shop with an explicit operator policy and conventional units. */
  default721Config?: {
    operatorPermissions: Revnet721OperatorPermissions;
    pricingDecimals?: number;
  };
  allowedPosts?: readonly REVCroptopAllowedPost[];
}) {
  const address = v6Address("REVDeployer", args.chainId);
  const revnetId = args.revnetId ?? 0n;

  // An omnichain revnet whose stages lack the sucker-deployment bit can never
  // be extended to new chains (or have failed sucker deploys retried): stages
  // are immutable and `deploySuckersFor` checks the CURRENT stage's bit. Refuse
  // to encode that foot-gun — `buildRevnetStageConfig` sets the bit by default.
  if (args.suckerConfig.deployerConfigurations.length > 0) {
    const blockedStage = args.config.stageConfigurations.findIndex(
      (stage) =>
        (Number(stage.extraMetadata) & REV_METADATA_ALLOW_SUCKER_DEPLOYMENT) ===
        0,
    );
    if (blockedStage !== -1) {
      throw new Error(
        `Stage ${blockedStage} does not set REV_METADATA_ALLOW_SUCKER_DEPLOYMENT ` +
          `(extraMetadata bit 2), so this cross-chain revnet could never deploy ` +
          `suckers during that stage — permanently. Build stages with ` +
          `buildRevnetStageConfig (which sets the bit by default), or OR the bit ` +
          `into extraMetadata.`,
      );
    }
  }

  // The deployer forwards msg.value to `JBProjects.createFor` for new revnets and
  // reverts on any value when initializing an existing project.
  if (revnetId === 0n && args.creationFee === undefined) {
    throw new Error("creationFee is required when deploying a new revnet");
  }
  const value = revnetId === 0n ? (args.creationFee as bigint) : 0n;

  if (args.tiered721Config && args.default721Config) {
    throw new Error(
      "Choose either tiered721Config or default721Config, not both.",
    );
  }
  if (
    !args.tiered721Config &&
    !args.default721Config &&
    args.allowedPosts?.length
  ) {
    throw new Error(
      "allowedPosts requires an explicit tiered721Config or default721Config.",
    );
  }
  const tiered721Config =
    args.tiered721Config ??
    (args.default721Config
      ? buildRevnet721Config({
          name: `${args.config.description.name} Store`,
          symbol: `${args.config.description.ticker}STORE`,
          contractUri: args.config.description.uri,
          salt: args.config.description.salt,
          pricing: resolve721PricingContext({
            currency: args.config.baseCurrency,
            accountingContexts: args.accountingContexts,
            decimals: args.default721Config.pricingDecimals,
          }),
          operatorPermissions: args.default721Config.operatorPermissions,
        })
      : undefined);
  if (tiered721Config) {
    // Validate supported units without changing deliberately supplied configuration.
    resolve721PricingContext(
      tiered721Config.baseline721HookConfiguration.tiersConfig,
    );
    return {
      chainId: args.chainId,
      address,
      abi: selectDeploymentAbi(revDeployerAbi, "deployFor", 6),
      functionName: "deployFor" as const,
      args: [
        revnetId,
        args.config,
        args.accountingContexts,
        args.suckerConfig,
        tiered721Config,
        args.allowedPosts ?? [],
      ] as const,
      value,
    };
  }
  return {
    chainId: args.chainId,
    address,
    abi: selectDeploymentAbi(revDeployerAbi, "deployFor", 4),
    functionName: "deployFor" as const,
    args: [
      revnetId,
      args.config,
      args.accountingContexts,
      args.suckerConfig,
    ] as const,
    value,
  };
}

/**
 * Build a `REVOwner.autoIssueFor` transaction request minting a stage's
 * pending auto-issuance to its beneficiary. Callable by anyone once the
 * stage has started; mints whatever `amountToAutoIssue` reports.
 */
export function buildAutoIssueTx(args: {
  chainId: JBChainId;
  revnetId: bigint;
  stageId: bigint;
  beneficiary: Address;
}) {
  return {
    chainId: args.chainId,
    address: v6Address("REVOwner", args.chainId),
    abi: revOwnerAbi,
    functionName: "autoIssueFor" as const,
    args: [args.revnetId, args.stageId, args.beneficiary] as const,
  };
}

/**
 * Read the token count (18-decimal fixed point) still available to
 * auto-issue to a beneficiary for a given stage.
 */
export async function getAmountToAutoIssue(
  client: PublicClient,
  args: {
    chainId: JBChainId;
    revnetId: bigint;
    stageId: bigint;
    beneficiary: Address;
  },
): Promise<bigint> {
  return client.readContract({
    address: v6Address("REVOwner", args.chainId),
    abi: revOwnerAbi,
    functionName: "amountToAutoIssue",
    args: [args.revnetId, args.stageId, args.beneficiary],
  });
}

/**
 * Read the timestamp when cash outs become available to the revnet's
 * participants (only set when an EXISTING revnet deploys onto a new
 * network). 0 or a past timestamp means cash outs are live. Loans are also
 * unavailable while the delay is active.
 */
export async function getCashOutDelay(
  client: PublicClient,
  args: { chainId: JBChainId; revnetId: bigint },
): Promise<bigint> {
  return client.readContract({
    address: v6Address("REVOwner", args.chainId),
    abi: revOwnerAbi,
    functionName: "cashOutDelayOf",
    args: [args.revnetId],
  });
}

/**
 * Read whether an address is the revnet's current operator (the account that
 * can manage splits and other operator-scoped powers).
 */
export async function isRevnetOperator(
  client: PublicClient,
  args: { chainId: JBChainId; revnetId: bigint; operator: Address },
): Promise<boolean> {
  return client.readContract({
    address: v6Address("REVOwner", args.chainId),
    abi: revOwnerAbi,
    functionName: "isOperatorOf",
    args: [args.revnetId, args.operator],
  });
}

/**
 * Read the tiered 721 hook registered for a revnet. Canonical v6 deployment
 * creates one even for an empty shop; zero means no hook is registered.
 */
export async function getRevnetTiered721Hook(
  client: PublicClient,
  args: { chainId: JBChainId; revnetId: bigint },
): Promise<Address> {
  return client.readContract({
    address: v6Address("REVOwner", args.chainId),
    abi: revOwnerAbi,
    functionName: "tiered721HookOf",
    args: [args.revnetId],
  });
}

